// The class a ship draws as, and the variant it draws with when the
// player never chose one -- both read out of ShipIcons.tsx, so a card
// can never disagree with the game about what a given ship looks like.
export const DEFAULT_SHIP_ICONS = {"corvette":"B","frigate":"B","destroyer":"B","freighter":"A","colony":"A"};
export const ICON_CLASS_FOR = {"corvette":"corvette","frigate":"frigate","destroyer":"destroyer","freighter":"freighter","colony":"colony","mega_destroyer":"destroyer","mobile_foundry":"freighter"};
